"use client";
import { ArtemisScope } from "./artemis-scope";
import View0 from "./components/social-proof/variants/01-evidence-brief";
import View1 from "./components/social-proof/variants/02-story-gallery";
import View2 from "./components/social-proof/variants/03-story-reel";
const variants = {"evidence-brief":View0,"story-gallery":View1,"story-reel":View2};
export interface ArtemisSocialProofProps { className?: string; variant?: "evidence-brief" | "story-gallery" | "story-reel"; }
export function ArtemisSocialProof({ className, variant = "evidence-brief" }: ArtemisSocialProofProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View/></div></ArtemisScope>;}
